using Geeratya.Core.Help;
using Geeratya.Core.Keymap;
using Geeratya.Core.Mouse;
using Geeratya.Core.State;
using Geeratya.Core.Text;

namespace Geeratya.Tui.Rendering;

/// <summary>
/// The help overlay: a title, the page names (a click on one shows it), the filter line while one is set, and the shown
/// page generated by <see cref="HelpPages"/>, scrolled.
/// </summary>
public sealed class HelpBodyRenderer : IBodyRenderer
{
    private const string Title = "Help";
    private const string PageSeparator = "  ";
    private const string FilterPrefix = "/";
    private const string CursorMark = "_";
    private const int PageRow = 1;

    public bool AppliesTo(AppState state)
    {
        return state.Mode == InputMode.Help && !state.MessagesOpen;
    }

    public IReadOnlyList<StyledLine> Render(AppState state, BodyContext context, int width, int height)
    {
        var lines = new List<StyledLine>
        {
            StyledLine.Of(Title, TextRole.Heading),
            PageNames(state, context.Keymap, width),
        };

        if (state.HelpFilter.Length > 0 || state.HelpFiltering)
        {
            var cursor = state.HelpFiltering ? CursorMark : string.Empty;

            lines.Add(StyledLine.Of($"{FilterPrefix}{state.HelpFilter}{cursor}", TextRole.Strong));
        }

        var page = HelpPages.Lines(state, context.Keymap).Skip(state.HelpScroll);

        lines.AddRange(page.Select(line => StyledLine.Of(line)));

        return lines;
    }

    /// <summary>The clickable page names, in body rows (the frame shifts them below the header).</summary>
    public static IReadOnlyList<OverlayRegion> PageRegions(AppState state, KeymapTable keymap, int width)
    {
        var regions = new List<OverlayRegion>();
        var column = 0;
        var names = HelpPages.Names(state, keymap);

        for (var index = FirstVisible(names, HelpPages.Current(state, keymap), width); index < names.Count && column < width; index++)
        {
            var cells = DisplayWidth.Of(names[index]);

            var visible = Math.Min(cells, width - column);

            regions.Add(new OverlayRegion(MouseTarget.HelpPage, PageRow, column, visible, 1, index));
            column += cells + PageSeparator.Length;
        }

        return regions;
    }

    /// <summary>
    /// The first page name shown, so the selected one is fully visible: names scroll off to the left only as far as needed.
    /// </summary>
    private static int FirstVisible(IReadOnlyList<string> names, int current, int width)
    {
        var first = 0;

        while (first < current && RowWidth(names, first, current) > width)
        {
            first++;
        }

        return first;
    }

    private static int RowWidth(IReadOnlyList<string> names, int first, int last)
    {
        var total = 0;

        for (var index = first; index <= last; index++)
        {
            total += DisplayWidth.Of(names[index]) + (index > first ? PageSeparator.Length : 0);
        }

        return total;
    }

    private static StyledLine PageNames(AppState state, KeymapTable keymap, int width)
    {
        var names = HelpPages.Names(state, keymap);
        var current = HelpPages.Current(state, keymap);
        var spans = new List<StyledSpan>();

        for (var index = FirstVisible(names, current, width); index < names.Count; index++)
        {
            if (spans.Count > 0)
            {
                spans.Add(new StyledSpan(PageSeparator, TextRole.Body));
            }

            spans.Add(new StyledSpan(names[index], index == current ? TextRole.Selected : TextRole.Muted));
        }

        return new StyledLine(spans);
    }
}
